}

#[derive(Clone, Debug, PartialEq, Eq, ToValue)]
#[value(rename_all = "camelCase")]
struct DurableOwnedThreeMemberUnsignedV1 {
    schema: String,
    anchor: DurableOwnedGroupAnchorV1,
