    StagingDrawing,
    StagingValue,
    StartingJournal,
    Journal,
    PublishingParentLease,
    PublishingDrawingLease,
    PublishingValueLease,
    AdoptingParent,
    AdoptingDrawing,
    AdoptingValue,
    ClearingParent,
    ClearingDrawing,
    ClearingValue,
    AwaitingAck,
    AbortingValue,
    AbortingDrawing,
    AbortingParent,
    ClosingJournal,
    Complete,
}

/// 📡️ One bounded coordinator result.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DurableOwnedThreeStoreCommitAdvanceV1 {
