            }
            fn shape_controlled<C: ::dsl::NativeSchemaControl>(control:&mut C)->Result<::dsl::Shape,::dsl::ValueError>{control.checkpoint()?;Ok(::dsl::Shape::Record(Self::__dsl_spec_producer()))}
